40	import { wantsFullOutput, truncateOneLine } from '../cli/output-verbosity.js';
41	import { readBrandEnv } from '../core/brand-env.js';
42	import { agentRoleIdsEqual } from '../core/agent-role-identity.js';
43	
44	// B-7c05 CHK-004: phases treated as terminal for the brief story_list default.
45	// Brief lists only NON-terminal (actionable) stories one-line each; the omitted
46	// terminal stories are still fully accounted for by the per-phase `_phases`
47	// counts + an explicit omitted count (non-silent filtering).
48	const STORY_LIST_TERMINAL_PHASES = new Set<string>(['DONE', 'DISCARDED', 'IDEA']);
49	
50	type StoryListRow = {
51	  storyId: string;
52	  phase: string;
53	  priority?: string;
54	  type?: string;
55	  title?: string;
56	  checklist?: string;
57	  bugs?: string;
58	  tests?: string;
59	  mainPhase?: string;
60	  labels?: string;
61	  bg?: string;
62	  [key: string]: unknown;
63	};
64	
65	/** One-line-per-story brief projection: drops the verbose `metrics`/`name` and truncates the title. */
66	function toBriefStoryRow(row: StoryListRow): Record<string, unknown> {
67	  return {
68	    storyId: row.storyId,
69	    phase: row.phase,
70	    ...(row.mainPhase ? { mainPhase: row.mainPhase } : {}),
71	    ...(row.priority ? { priority: row.priority } : {}),
72	    ...(row.type ? { type: row.type } : {}),
73	    title: truncateOneLine(row.title, 80),
74	    ...(row.checklist ? { checklist: row.checklist } : {}),
75	    ...(row.bugs ? { bugs: row.bugs } : {}),
76	    ...(row.tests ? { tests: row.tests } : {}),
77	    ...(row.labels ? { labels: row.labels } : {}),
78	    ...(row.bg ? { bg: row.bg } : {}),
79	  };
80	}
81	
82	/** B-45ed CHK-008: Returns true if the story's background.md file exists. */
83	function hasBackground(store: StoryStore, storyId: string): boolean {
84	  return existsSync(store.storyFilePath(storyId, 'background.md'));
85	}
86	
87	// ─── Non-terminal phases for zombie detection ──────────────────────────────
88	
89	const NON_TERMINAL_PHASES = new Set<string>([
90	  'INIT', 'INIT_CHECK', 'PLAN', 'DEV', 'REVIEW',
91	  'TEST_CASE', 'TEST_CASE_REVIEW', 'TEST',
92	]);
93	
94	interface ZombieInfo {
95	  storyId: string;
96	  phase: string;
97	  branch: string;
98	  branchExists: boolean;
99	  branchMerged: boolean;
100	  worktreeExists: boolean;
101	  worktreePath?: string;
102	  worktreeForeignPath?: boolean;
103	}
104	
105	interface StoryResidueInfo {
106	  storyId: string;
107	  phase: string;
108	  path: string;
109	  safe: boolean;
110	  status: string;
111	}
112	
113	interface IntentFixtureLocation {
114	  file: string;
115	  line: number;
116	  name: string;
117	}
118	
119	const INIT_REVIEWER_STORY_SCOPE_MUTATION_BLOCKED_AGENTS = new Set([
120	  'proof-or-stop-review-story-init',
121	  'proof-or-stop-product-reviewer',
122	]);
123	
124	const STORY_LEVEL_SCOPE_FIELDS = ['title', 'description', 'source', 'depends'] as const;
125	type StoryLevelScopeField = typeof STORY_LEVEL_SCOPE_FIELDS[number];
126	type StoryGetArgs = { storyId: string; detail?: boolean; slim?: boolean; fields?: string[] };
127	
128	function pickTopLevelFields<T extends Record<string, unknown>>(value: T, fields?: string[]): Partial<T> {
129	  const requested = (fields || []).map(field => field.trim()).filter(Boolean);
130	  if (requested.length === 0) return value;
131	  const selected: Partial<T> = {};
132	  for (const field of requested) {
133	    if (Object.prototype.hasOwnProperty.call(value, field)) {
134	      selected[field as keyof T] = value[field as keyof T];
135	    }
136	  }
137	  return selected;
138	}
139	
140	function isLegacyIntentRef(ref: string): boolean {
141	  return /^CHK-\d+:(happy|edge|adversarial):\d+$/.test(ref);
142	}
143	
144	function lineOfCaseName(raw: string, caseName: unknown): number {
145	  if (typeof caseName !== 'string') return 0;
146	  const compactIdx = raw.indexOf(`"name":"${caseName}"`);
147	  const prettyIdx = raw.indexOf(`"name": "${caseName}"`);
148	  const idx = compactIdx >= 0 ? compactIdx : prettyIdx;
149	  return idx >= 0 ? raw.substring(0, idx).split('\n').length : 0;
150	}
151	
152	function relativeFixtureFile(fixturesDir: string, filePath: string): string {
153	  return filePath
154	    .replace(fixturesDir + '/', '')
155	    .replace(fixturesDir + '\\', '');
156	}
157	
158	function collectStoryIntentFixtures(
159	  fixturesDir: string,
160	  storyId: string,
161	): Map<string, IntentFixtureLocation> {
162	  const refs = new Map<string, IntentFixtureLocation>();
163	  if (!existsSync(fixturesDir)) return refs;
164	
165	  const scopedPrefix = `${storyId}:`;
